const state = items[0].json;

// Support webhook payloads wrapped under body
const body = state.body || {};
if (!state.plan && body.plan) state.plan = body.plan;
if (!state.authorization && body.authorization) state.authorization = body.authorization;
if (!state.payload && body.payload) state.payload = body.payload;

state.payload = state.payload || {};
state.authorization = state.authorization || {};

const registryDefaults = {
