};

if (!state.payload.registry) {
  state.payload.registry = registryDefaults;
}

const registry = state.payload.registry || {};
const capabilityItems = Array.isArray(registry?.capabilities?.items) ? registry.capabilities.items : [];
const accessByTool = capabilityItems.reduce((acc, item) => {
  if (item && item.id) acc[item.id] = item.access || item.mode;
  return acc;
}, {});

const steps = state.plan?.steps;
const readOnlyPlan = Array.isArray(steps) && steps.length > 0 && steps.every((step) => {
  return ['read', 'read_only', 'readonly'].includes(accessByTool[step.tool_ref]);
});

const mode = state.authorization?.mode;
const authorized = (mode === 'auto_approved' && readOnlyPlan) || ['preapproved', 'human_approved'].includes(mode);

if (!authorized) {
  throw new Error('Execution not authorized');
}

state.execution = state.execution || {};
state.execution.status = 'running';
state.execution.cursor = 0;
state.execution.results = [];

if (!Array.isArray(steps) || steps.length === 0) {
  throw new Error('plan.steps missing');
}

return [{ json: state }];

const { envelope, step } = items[0].json;

function resolveTemplate(value, results) {
  if (typeof value === 'string') {
    return value.replace(/\{\{\s*\$step\[(\d+)\]\.outputs\.([^}]+)\}\}/g, (_match, indexStr, path) => {
      const index = Number(indexStr);
      const result = results[index]?.result;
      if (result === undefined || result === null) return '';
      const parts = path.split('.');
      let current = result;
      for (const part of parts) {
        if (current && Object.prototype.hasOwnProperty.call(current, part)) {
          current = current[part];
        } else {
          return '';
        }
      }
      if (typeof current === 'string' || typeof current === 'number' || typeof current === 'boolean') {
        return String(current);
      }
      return JSON.stringify(current);
    });
  }

  if (Array.isArray(value)) {
    return value.map((item) => resolveTemplate(item, results));
  }

  if (value && typeof value === 'object') {
    if (Object.prototype.hasOwnProperty.call(value, '$ref')) {
      return value;
    }
    const output = {};
    for (const [key, nested] of Object.entries(value)) {
      output[key] = resolveTemplate(nested, results);
    }
    return output;
  }

  return value;
}

const resolvedArgs = resolveTemplate(step.args || step.params || {}, envelope.execution?.results || []);
const resolvedStep = {
  ...step,
  args: resolvedArgs,
  params: resolvedArgs
};

return [{
  json: {
    envelope,
    step: resolvedStep
  }
}];

const { envelope, step } = items[0].json;

const outputs = items.map((item) => {
  const { result, data } = item.json;
  return result !== undefined ? result : data;
});

const errors = items
  .map((item) => item.json.error)
  .filter((error) => error !== null && error !== undefined);

const output = outputs.length === 1 ? outputs[0] : outputs;
const error = errors.length > 0 ? errors[0] : null;

function pickFields(obj, fields) {
  if (!obj || typeof obj !== 'object') return obj;
  const out = {};
  for (const field of fields) {
    if (Object.prototype.hasOwnProperty.call(obj, field)) {
      out[field] = obj[field];
    }
  }
  return out;
}

function getByPath(obj, path) {
  if (!path || !obj) return undefined;
  const parts = String(path).split('.');
  let current = obj;
  for (const part of parts) {
    if (current === null || current === undefined) return undefined;
    const index = Number(part);
    if (Array.isArray(current) && Number.isInteger(index) && String(index) === part) {
      current = current[index];
    } else {
      current = current[part];
    }
  }
  return current;
}

function resolveOutputPath(value, outputPath) {
  if (!outputPath) return value;
  const paths = Array.isArray(outputPath) ? outputPath : [outputPath];
  for (const path of paths) {
    const resolved = getByPath(value, path);
    if (resolved !== undefined) return resolved;
  }
  return value;
}

function findToolSpec(registry, toolRef) {
  if (!registry || !toolRef) return null;
  if (registry.tools && !Array.isArray(registry.tools) && registry.tools[toolRef]) {
    return registry.tools[toolRef];
  }
  const list = Array.isArray(registry.items)
    ? registry.items
    : Array.isArray(registry.tools)
      ? registry.tools
      : Array.isArray(registry.tools?.items)
        ? registry.tools.items
        : [];
  return list.find((item) => item.id === toolRef) || null;
}

function applyNormalize(value, normalize) {
  if (!normalize) return value;
  let current = resolveOutputPath(value, normalize.output_path);
  if (normalize.pick && Array.isArray(normalize.pick)) {
    if (Array.isArray(current)) {
      current = current.map((entry) => pickFields(entry, normalize.pick));
    } else if (current && typeof current === 'object') {
      if (normalize.wrap && Array.isArray(current[normalize.wrap])) {
        current = {
          ...current,
          [normalize.wrap]: current[normalize.wrap].map((entry) => pickFields(entry, normalize.pick))
        };
      } else {
        current = pickFields(current, normalize.pick);
      }
    }
  }
  return current;
}

function normalizeOutput(step, value) {
  const spec = step?.outputs;
  if (!spec || typeof spec !== 'object' || Array.isArray(spec)) return value;
  const keys = Object.keys(spec);
  if (keys.length === 0) return value;
  if (keys.length === 1) {
    const key = keys[0];
    if (value && typeof value === 'object' && !Array.isArray(value) && Object.prototype.hasOwnProperty.call(value, key)) {
      return value;
    }
    return { [key]: value };
  }
  if (value && typeof value === 'object' && !Array.isArray(value)) {
    return value;
  }
  return value;
}

const registry = envelope?.payload?.registry || envelope?.registry || null;
const toolSpec = findToolSpec(registry, step?.tool_ref || step?.tool || step?.ref || '');
const normalizedValue = applyNormalize(output, toolSpec?.normalize);
const normalizedOutput = normalizeOutput(step, normalizedValue);

envelope.execution.results.push({
  step,
  status: error ? 'failed' : 'ok',
  result: normalizedOutput ?? null,
  error
});

if (error) {
  envelope.execution.status = 'failed';
} else {
  envelope.execution.cursor = (envelope.execution.cursor || 0) + 1;
  if (envelope.execution.cursor >= (envelope.plan?.steps?.length || 0)) {
    envelope.execution.status = 'completed';
  }
}

return [{ json: envelope }];

const state = items[0].json;

const status = state.execution?.status || 'completed';
const results = Array.isArray(state.execution?.results) ? state.execution.results : [];

const normalizedResults = results.map((entry, index) => {
  const step = entry.step || {};
  return {
    id: step.id || `step_${index}`,
    tool_ref: step.tool_ref || step.ref || step.tool || null,
    status: entry.status || 'ok',
    inputs: step.inputs || step.args || {},
    outputs: step.outputs || {},
    result: entry.result ?? null,
    error: entry.error ?? null
  };
});

const firstError = results.find((entry) => entry?.error)?.error ?? null;

const sessionId = state.execution?.session_id
  || state.payload?.context?.memory?.session_id
  || state.payload?.context?.session_id
  || state.payload?.context?.correlation_id
  || 'unknown';

const contractVersion = state.execution?.contract_version
  || state.plan?.contract_version
  || state.payload?.context?.contract_version
  || '1.0';

state.output = {
  contract_version: String(contractVersion),
  session_id: String(sessionId),
  status,
  result: {
    summary: `Execution ${status}`,
    steps: normalizedResults
  },
  artifacts: null,
  logs: null,
  error: status === 'failed' ? (firstError || 'Execution failed') : null
};

return [{ json: state }];

const state = items[0].json;

const steps = state.plan?.steps || [];
const cursor = state.execution?.cursor ?? 0;
const step = steps[cursor];

if (!step) {
  return [{ json: state }];
}

return [{
  json: {
    envelope: state,
    step
  }
}];

const state = items[0].json;
const total = Array.isArray(state.plan?.steps) ? state.plan.steps.length : 0;
state.execution = state.execution || {};
state.execution.has_next = (state.execution.cursor || 0) < total;
return [{ json: state }];
